def validate_candidate(result, request, allowed_tools):
    if not result.answer.strip(): raise ValueError('empty answer')
    for call in result.tool_calls:
        if call.name not in allowed_tools: raise PermissionError('tool not allowed')
        if call.arguments.get('tenant_id') != request['tenant_id']:
            raise PermissionError('tenant mismatch')
    if request['intent'] == 'refund' and request['amount'] >= 10000 and not result.approval_required:
        raise PermissionError('human approval required')
    return True
